INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.role_key='super_admin';
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.module IN ('dashboard','catalog','vendors','purchase_requests','requisitions','quotations','purchase_orders','approvals','deliveries','reports','imports') WHERE r.role_key='procurement_officer';
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.module IN ('dashboard','purchase_requests','approvals','budgets','invoices','payments','reports') WHERE r.role_key='finance_officer';
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.permission_key IN ('dashboard.view','purchase_requests.view','purchase_requests.create','reports.view') WHERE r.role_key='employee';
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.permission_key IN ('dashboard.view','purchase_requests.view','purchase_requests.create','purchase_requests.manage','approvals.act','reports.view') WHERE r.role_key='department_manager';
