INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON (r.role_key='super_admin') OR (r.role_key='it_manager' AND p.module IN ('dashboard','organization','catalog','vendors','purchase_requests','requisitions','quotations','purchase_orders','approvals','deliveries','reports','imports')) OR (r.role_key='procurement_officer' AND p.module IN ('dashboard','catalog','vendors','purchase_requests','requisitions','quotations','purchase_orders','approvals','deliveries','reports','imports')) OR (r.role_key='finance_officer' AND p.module IN ('dashboard','purchase_requests','approvals','budgets','invoices','payments','reports')) OR (r.role_key='department_manager' AND p.permission_key IN ('dashboard.view','purchase_requests.view','purchase_requests.create','purchase_requests.manage','approvals.view','approvals.act','reports.view')) OR (r.role_key='employee' AND p.permission_key IN ('dashboard.view','purchase_requests.view','purchase_requests.create')) OR (r.role_key='auditor' AND p.permission_key IN ('dashboard.view','reports.view','reports.export','audit.view'));
